250	// GetUserWebhookSigningSecret reveals the signing secret for a single webhook.
251	// This is the only endpoint that returns the secret value; it is gated to the
252	// webhook owner (or an admin) and the secret is never included in list/create/update responses.
253	func (s *APIV1Service) GetUserWebhookSigningSecret(ctx context.Context, request *v1pb.GetUserWebhookSigningSecretRequest) (*v1pb.GetUserWebhookSigningSecretResponse, error) {
254		user, webhookID, err := s.resolveUserAndWebhookIDFromName(ctx, request.Name)
255		if err != nil {
256			return nil, status.Errorf(codes.InvalidArgument, "invalid webhook name: %v", err)
257		}
258		userID := user.ID
259	
260		if _, err := s.authorizeUserResourceAccess(ctx, userID, true); err != nil {
261			return nil, err
262		}
263	
264		webhooks, err := s.Store.GetUserWebhooks(ctx, userID)
265		if err != nil {
266			return nil, status.Errorf(codes.Internal, "failed to get user webhooks: %v", err)
267		}
268	
269		for _, webhook := range webhooks {
270			if webhook.Id == webhookID {
271				return &v1pb.GetUserWebhookSigningSecretResponse{SigningSecret: webhook.SigningSecret}, nil
272			}
273		}
274	
275		return nil, status.Errorf(codes.NotFound, "webhook not found")
276	}
